#include <iostream>
using namespace std;

class Complex {
private:
    float real;
    float imag;

public:
    Complex(float r = 0, float i = 0) : real(r), imag(i) {}

    // Overloading + operator
    Complex operator+(const Complex& obj) {
        return Complex(real + obj.real, imag + obj.imag);
    }

    // Overloading - operator
    Complex operator-(const Complex& obj) {
        return Complex(real - obj.real, imag - obj.imag);
    }

    void display() const {
        cout << real << (imag >= 0 ? " + " : " - ") << abs(imag) << "i" << endl;
    }
};

int main() {
    Complex c1(5.5, 4.5);
    Complex c2(2.5, 1.5);

    Complex sum = c1 + c2;
    Complex diff = c1 - c2;

    cout << "Complex 1: "; c1.display();
    cout << "Complex 2: "; c2.display();
    cout << "Sum: "; sum.display();
    cout << "Difference: "; diff.display();

    return 0;
}
