#include <iostream>
using namespace std;

class Base {
public:
    // Early binding (static linking)
    void show() {
        cout << "Base class show() - Early Binding" << endl;
    }

    // Late binding (dynamic linking) using virtual keyword
    virtual void print() {
        cout << "Base class print() - Late Binding" << endl;
    }
};

class Derived : public Base {
public:
    void show() {
        cout << "Derived class show()" << endl;
    }

    void print() override {
        cout << "Derived class print()" << endl;
    }
};

int main() {
    Base* basePtr;
    Derived derivedObj;

    basePtr = &derivedObj;

    // Early binding: Compiler looks at pointer type (Base*), so Base's show() is called
    basePtr->show(); 

    // Late binding: Compiler looks at object content (Derived), so Derived's print() is called
    basePtr->print();

    return 0;
}
