#include <iostream>
#include <stack>
using namespace std;

int main() {
    // Create a stack of integers
    stack<int> s;

    // 1. push() - Adds elements to the top of the stack
    s.push(10);
    s.push(20);
    s.push(30);
    cout << "Pushed 10, 20, 30 onto the stack.\n";

    // 2. size() - Returns the number of elements
    cout << "Current stack size: " << s.size() << endl;

    // 3. empty() - Checks if the stack is empty
    if (!s.empty()) {
        // 4. top() - Accesses the top element without removing it
        cout << "Top element is: " << s.top() << endl;
    }

    cout << "Popping elements from stack: ";
    while (!s.empty()) {
        cout << s.top() << " "; 
        // 5. pop() - Removes the top element
        s.pop(); 
    }
    cout << endl;

    if (s.empty()) {
        cout << "Stack is now empty.\n";
    }

    return 0;
}
