#include <iostream>
using namespace std;

class Triangle {
private:
    float base;
    float height;

public:
    // (i) No parameter constructor
    Triangle() {
        base = 0;
        height = 0;
    }

    // (ii) Two parameters constructor
    Triangle(float b, float h) {
        base = b;
        height = h;
    }

    // (iii) One parameter constructor
    Triangle(float b) {
        base = b;
        height = 4;
    }

    // (iv) Copy constructor
    Triangle(const Triangle& t) {
        base = t.base;
        height = t.height;
    }

    // Function to calculate and return area
    float calculateArea() {
        return 0.5 * base * height;
    }

    void displayArea(string name) {
        cout << "Area of " << name << " (Base: " << base 
             << ", Height: " << height << ") is: " << calculateArea() << endl;
    }
};

int main() {
    // Using no parameter constructor
    Triangle t1;
    t1.displayArea("Triangle 1 (No params)");

    // Using two parameter constructor
    Triangle t2(10.0, 5.0);
    t2.displayArea("Triangle 2 (Two params)");

    // Using one parameter constructor
    Triangle t3(6.0);
    t3.displayArea("Triangle 3 (One param)");

    // Using copy constructor
    Triangle t4 = t2; // or Triangle t4(t2);
    t4.displayArea("Triangle 4 (Copy of Triangle 2)");

    return 0;
}
