#include <iostream>
#include <string>
using namespace std;

// Base Class 1
class Student {
protected:
    int rollNo;
    string name;
public:
    void getStudentDetails() {
        cout << "Enter Roll No: ";
        cin >> rollNo;
        cout << "Enter Name: ";
        cin.ignore();
        getline(cin, name);
    }
    void displayStudentDetails() {
        cout << "\nRoll No: " << rollNo << "\nName: " << name << endl;
    }
};

// Derived Class 1 (Inherits Student)
class Marks : public Student {
protected:
    float mark1, mark2;
public:
    void getMarks() {
        cout << "Enter marks for two subjects: ";
        cin >> mark1 >> mark2;
    }
    void displayMarks() {
        cout << "Marks: Subject 1 = " << mark1 << ", Subject 2 = " << mark2 << endl;
    }
};

// Base Class 2
class Sports {
protected:
    float sportsScore;
public:
    void getSportsScore() {
        cout << "Enter sports score: ";
        cin >> sportsScore;
    }
    void displaySportsScore() {
        cout << "Sports Score: " << sportsScore << endl;
    }
};

// Derived Class 2 (Multiple Inheritance from Marks and Sports)
class Result : public Marks, public Sports {
private:
    float total;
    float average;
public:
    void calculateResult() {
        total = mark1 + mark2 + sportsScore;
        average = total / 3.0;
    }
    void displayResult() {
        displayStudentDetails();
        displayMarks();
        displaySportsScore();
        cout << "Total Score: " << total << endl;
        cout << "Average: " << average << endl;
    }
};

int main() {
    Result res;
    cout << "--- Enter Student Data ---\n";
    res.getStudentDetails();
    res.getMarks();
    res.getSportsScore();

    res.calculateResult();

    cout << "\n--- Result --- ";
    res.displayResult();

    return 0;
}
